function Invoke-AgentPython {
    param([Parameter(Mandatory = $true)][string[]]$Arguments)
    $agentPy = Join-Path $env:USERPROFILE '.ai-workspace\venv\Scripts\python.exe'
    if (Test-Path -LiteralPath $agentPy) {
        & $agentPy @Arguments
        return $LASTEXITCODE
    }
    python @Arguments
    return $LASTEXITCODE
}

function Apply-CodexProvider {
    param($ProviderConfig, [string]$ProviderId)
    $sc = $ProviderConfig.settings_config
    $cc = Get-Content $ccSettingsPath -Raw | ConvertFrom-Json
    $preserveOAuth = ($ProviderId -eq 'codex-official') -or ($cc.preserveCodexOfficialAuthOnSwitch -eq $true -and $ProviderId -match 'official$')
    $utf8NoBom = New-Object System.Text.UTF8Encoding $false

    if ($sc.config) {
        $configBody = [string]$sc.config
        if ($preserveOAuth) {
            $configBody = Repair-CodexOfficialToml $configBody
        }
        if ((Test-Path -LiteralPath $codexConfigPath) -and (Test-Path -LiteralPath $patchCodexProviderPy)) {
            $providerTmp = Join-Path $env:TEMP "cc-sync-codex-provider-$ProviderId.toml"
            [System.IO.File]::WriteAllText($providerTmp, $configBody, $utf8NoBom)
            $exit = Invoke-AgentPython @($patchCodexProviderPy, $codexConfigPath, $providerTmp)
            Remove-Item $providerTmp -ErrorAction SilentlyContinue
            if ($exit -ne 0) {
                Write-Warning "patch-codex-provider-config failed; falling back to full provider config write"
                [System.IO.File]::WriteAllText($codexConfigPath, $configBody, $utf8NoBom)
            }
        } else {
            [System.IO.File]::WriteAllText($codexConfigPath, $configBody, $utf8NoBom)
        }
    }
    if ($sc.auth) {
        $auth = if (Test-Path $codexAuthPath) { Get-Content $codexAuthPath -Raw | ConvertFrom-Json } else { [ordered]@{} }
        $liveIsOAuth = ($auth.auth_mode -eq 'chatgpt') -and $auth.tokens
        if ($preserveOAuth -and $liveIsOAuth) {
            # Keep fresh ChatGPT OAuth from live session; do not overwrite with stale DB tokens.
            if ($sc.auth.OPENAI_API_KEY) {
                $auth.OPENAI_API_KEY = $null
            }
        } else {
            foreach ($p in $sc.auth.PSObject.Properties) {
                $auth | Add-Member -NotePropertyName $p.Name -NotePropertyValue $p.Value -Force
            }
        }
        $authJson = $auth | ConvertTo-Json -Depth 8
        [System.IO.File]::WriteAllText($codexAuthPath, $authJson, $utf8NoBom)
    }

    if (Test-Path -LiteralPath $syncCodexPlusRelayPy) {
        $providerJson = Join-Path $env:TEMP "cc-sync-codex-provider-$ProviderId.json"
        @{
            id = $ProviderId
            name = $ProviderConfig.name
            website_url = $ProviderConfig.website_url
            settings_config = $sc
        } | ConvertTo-Json -Depth 20 | Set-Content -Path $providerJson -Encoding utf8
        $exit = Invoke-AgentPython @($syncCodexPlusRelayPy, $providerJson)
        Remove-Item $providerJson -ErrorAction SilentlyContinue
        if ($exit -ne 0) {
            Write-Warning "sync-codex-plus-relay-from-cc failed (Codex++ may stay on old relay profile)"
        }
    }
}

